import{c as l,Q as i,j as t,m as r}from"./chunks/framework.BPKcPtvA.js";const c=JSON.parse('{"title":"常见问题与技术排障 - 解决 Action Blocked 等错误","description":"整理了遭遇 Action Blocked 风控、提现卡顿、私钥报错、HYPE 质押赎回冷却等常见疑难解答。","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://hyperliquidrecoverybot.github.io/zh/faq"}],["link",{"rel":"alternate","hreflang":"en","href":"https://hyperliquidrecoverybot.github.io/en/faq"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://hyperliquidrecoverybot.github.io/zh/faq"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://hyperliquidrecoverybot.github.io/en/faq"}],["meta",{"name":"keywords","content":"Hyperliquid常见问题, 解决Action Blocked, 绕过风控提现, 找回限制资金, HYPE质押赎回"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:title","content":"常见问题与技术排障 - 解决 Action Blocked 等错误"}],["meta",{"property":"og:description","content":"整理了遭遇 Action Blocked 风控、提现卡顿、私钥报错、HYPE 质押赎回冷却等常见疑难解答。"}],["meta",{"property":"og:url","content":"https://hyperliquidrecoverybot.github.io/zh/faq"}],["meta",{"name":"twitter:card","content":"summary"}],["meta",{"name":"twitter:title","content":"常见问题与技术排障 - 解决 Action Blocked 等错误"}],["meta",{"name":"twitter:description","content":"整理了遭遇 Action Blocked 风控、提现卡顿、私钥报错、HYPE 质押赎回冷却等常见疑难解答。"}]]},"headers":[],"relativePath":"zh/faq.md","filePath":"zh/faq.md","lastUpdated":null}'),e={name:"zh/faq.md"};function o(n,a,h,s,d,u){return i(),t("div",null,[...a[0]||(a[0]=[r('<h1 id="hyperliquid-风险地址与提现受限-常见故障排查-faq" tabindex="-1">Hyperliquid 风险地址与提现受限：常见故障排查 (FAQ) <a class="header-anchor" href="#hyperliquid-风险地址与提现受限-常见故障排查-faq" aria-label="Permalink to &quot;Hyperliquid 风险地址与提现受限：常见故障排查 (FAQ)&quot;">​</a></h1><p>本指南专为遭遇资金受困或被标记为高风险地址的 Hyperliquid 账户提供技术排障方案，涵盖提现失败、资产转移及质押资产分阶段处理等常见问题。</p><h2 id="🤖-机器人基础问题" tabindex="-1">🤖 机器人基础问题 <a class="header-anchor" href="#🤖-机器人基础问题" aria-label="Permalink to &quot;🤖 机器人基础问题&quot;">​</a></h2><h3 id="q-什么是-hyperliquid-recovery-bot" tabindex="-1">Q: 什么是 Hyperliquid Recovery Bot？ <a class="header-anchor" href="#q-什么是-hyperliquid-recovery-bot" aria-label="Permalink to &quot;Q: 什么是 Hyperliquid Recovery Bot？&quot;">​</a></h3><p><strong>A:</strong> Hyperliquid Recovery Bot 是一个专业的 Telegram 机器人，专为 Hyperliquid 生态系统用户设计，帮助用户从被标记为高风险的地址中安全地恢复数字资产。</p><h3 id="q-机器人是免费使用的吗" tabindex="-1">Q: 机器人是免费使用的吗？ <a class="header-anchor" href="#q-机器人是免费使用的吗" aria-label="Permalink to &quot;Q: 机器人是免费使用的吗？&quot;">​</a></h3><p><strong>A:</strong> 地址检测完全免费。资产恢复服务收费：</p><ul><li><strong>服务费</strong>: 总资产价值的 0.5%（最低 1 USDC）</li><li><strong>提现手续费</strong>: 2 USDC（Hyperliquid 平台）</li><li><strong>示例</strong>: 恢复 $1,000 → 支付 $7 → 收到 $993</li></ul><h3 id="q-如何确认这是官方机器人" tabindex="-1">Q: 如何确认这是官方机器人？ <a class="header-anchor" href="#q-如何确认这是官方机器人" aria-label="Permalink to &quot;Q: 如何确认这是官方机器人？&quot;">​</a></h3><p><strong>A:</strong> 请确保使用官方链接访问机器人：</p><ul><li><strong>官方地址</strong>: <a href="https://t.me/HyperliquidRecoveryBot?start=vsAPDn_gitbook" target="_blank" rel="noreferrer">https://t.me/HyperliquidRecoveryBot</a></li><li><strong>用户名</strong>: <a href="https://t.me/HyperliquidRecoveryBot?start=vsAPDn_gitbook" target="_blank" rel="noreferrer">@HyperliquidRecoveryBot</a></li><li><strong>验证标识</strong>: 查看机器人的功能菜单和界面特征</li></ul><h3 id="q-机器人支持哪些语言" tabindex="-1">Q: 机器人支持哪些语言？ <a class="header-anchor" href="#q-机器人支持哪些语言" aria-label="Permalink to &quot;Q: 机器人支持哪些语言？&quot;">​</a></h3><p><strong>A:</strong> 目前支持：</p><ul><li><strong>中文</strong>: 完整的简体中文支持</li><li><strong>英文</strong>: 完整的英文支持</li></ul><h3 id="q-机器人的工作时间是什么" tabindex="-1">Q: 机器人的工作时间是什么？ <a class="header-anchor" href="#q-机器人的工作时间是什么" aria-label="Permalink to &quot;Q: 机器人的工作时间是什么？&quot;">​</a></h3><p><strong>A:</strong> 机器人通常可随时使用。若遇到网络或平台波动，建议稍后重试，并在网络状况良好时进行重要操作。</p><h2 id="🔍-地址检测问题" tabindex="-1">🔍 地址检测问题 <a class="header-anchor" href="#🔍-地址检测问题" aria-label="Permalink to &quot;🔍 地址检测问题&quot;">​</a></h2><h3 id="q-支持哪些地址格式" tabindex="-1">Q: 支持哪些地址格式？ <a class="header-anchor" href="#q-支持哪些地址格式" aria-label="Permalink to &quot;Q: 支持哪些地址格式？&quot;">​</a></h3><p><strong>A:</strong> 支持标准的 Hyperliquid 地址格式：</p><ul><li><strong>长度</strong>: 42 个字符（包含 0x 前缀）</li><li><strong>格式</strong>: 0x + 40 位十六进制字符</li><li><strong>示例</strong>: 0x1234567890123456789012345678901234567890</li></ul><h3 id="q-检测需要多长时间" tabindex="-1">Q: 检测需要多长时间？ <a class="header-anchor" href="#q-检测需要多长时间" aria-label="Permalink to &quot;Q: 检测需要多长时间？&quot;">​</a></h3><p><strong>A:</strong> 通常在几秒到几分钟内完成，具体时间取决于：</p><ul><li>网络状况</li><li>Hyperliquid API 响应速度</li><li>地址的资产数量和复杂度</li></ul><h3 id="q-检测到的资产信息准确吗" tabindex="-1">Q: 检测到的资产信息准确吗？ <a class="header-anchor" href="#q-检测到的资产信息准确吗" aria-label="Permalink to &quot;Q: 检测到的资产信息准确吗？&quot;">​</a></h3><p><strong>A:</strong> 是的，机器人使用 Hyperliquid 官方 API 获取实时数据，信息准确可靠。但请注意：</p><ul><li>价格信息可能有 1-2 分钟延迟</li><li>某些新代币可能暂时无价格信息</li><li>网络拥堵可能影响数据更新</li></ul><h3 id="q-为什么有些资产没有显示价格" tabindex="-1">Q: 为什么有些资产没有显示价格？ <a class="header-anchor" href="#q-为什么有些资产没有显示价格" aria-label="Permalink to &quot;Q: 为什么有些资产没有显示价格？&quot;">​</a></h3><p><strong>A:</strong> 可能的原因：</p><ul><li>新上线的代币暂无价格数据</li><li>流动性较低的代币</li><li>价格 API 暂时不可用</li><li>代币已停止交易</li></ul><h3 id="q-可以检测多个地址吗" tabindex="-1">Q: 可以检测多个地址吗？ <a class="header-anchor" href="#q-可以检测多个地址吗" aria-label="Permalink to &quot;Q: 可以检测多个地址吗？&quot;">​</a></h3><p><strong>A:</strong> 当前每次检测仅处理一个地址，您可以连续多次检测不同地址。</p><h3 id="q-检测历史会保存多久" tabindex="-1">Q: 检测历史会保存多久？ <a class="header-anchor" href="#q-检测历史会保存多久" aria-label="Permalink to &quot;Q: 检测历史会保存多久？&quot;">​</a></h3><p><strong>A:</strong> 本公开文档不将检测历史视为长期记录，请以当前结果页作为主要参考。</p><h2 id="🛠️-资产恢复问题" tabindex="-1">🛠️ 资产恢复问题 <a class="header-anchor" href="#🛠️-资产恢复问题" aria-label="Permalink to &quot;🛠️ 资产恢复问题&quot;">​</a></h2><h3 id="q-可以恢复哪些资产类型" tabindex="-1">Q: 可以恢复哪些资产类型？ <a class="header-anchor" href="#q-可以恢复哪些资产类型" aria-label="Permalink to &quot;Q: 可以恢复哪些资产类型？&quot;">​</a></h3><p><strong>A:</strong> 机器人可以恢复 4 种资产类型：</p><ul><li>✅ <strong>现货资产</strong>: USDC、ETH、BTC 等代币</li><li>✅ <strong>永续合约</strong>: 多头/空头持仓</li><li>✅ <strong>金库资产</strong>: 存放在金库中的资产（如果未锁定）</li><li>✅ <strong>质押资产</strong>: 质押给验证者的 HYPE 代币（需要等待期）</li></ul><h3 id="q-什么情况下需要使用该工具进行恢复提现" tabindex="-1">Q: 什么情况下需要使用该工具进行恢复提现？ <a class="header-anchor" href="#q-什么情况下需要使用该工具进行恢复提现" aria-label="Permalink to &quot;Q: 什么情况下需要使用该工具进行恢复提现？&quot;">​</a></h3><p><strong>A:</strong> 当您的地址被标记且资金受困时：</p><ul><li>可在前端连接该地址进行查看，但通常无法发起 Hyperliquid 上的常规资产操作（如转账、交易或提现）。</li><li>前端界面可能会阻断操作并弹出类似如下官方系统日志提示：</li></ul><div class="language-log vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">log</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Action blocked: Address flagged for suspicious activity. Your address has been flagged as high risk by a third-party screening tool. This frontend interface does not support connection to the Hyperliquid blockchain by high risk addresses.</span></span></code></pre></div><ul><li>出现覆盖全屏的红色风险提示遮罩，且常见的操作按钮可能会受限或置灰。</li><li>与资产相关的操作区域可能受限，无法正常完成关键步骤。</li></ul><h3 id="q-恢复过程需要多长时间" tabindex="-1">Q: 恢复过程需要多长时间？ <a class="header-anchor" href="#q-恢复过程需要多长时间" aria-label="Permalink to &quot;Q: 恢复过程需要多长时间？&quot;">​</a></h3><p><strong>A:</strong> 现货和永续资产通常较快完成。质押资产按当前状态不同，通常需要 2-3 次运行：</p><ul><li><strong>优化路径（2 次）</strong>: 若账户已有 undelegated 余额，首次可立即处理一部分</li><li><strong>标准路径（3 次）</strong>: 若仅 delegated 余额，通常需经历 1 天 + 7 天等待窗口</li></ul><h3 id="q-恢复过程可以取消吗" tabindex="-1">Q: 恢复过程可以取消吗？ <a class="header-anchor" href="#q-恢复过程可以取消吗" aria-label="Permalink to &quot;Q: 恢复过程可以取消吗？&quot;">​</a></h3><p><strong>A:</strong> 一旦确认开始恢复执行，通常不能中途取消。建议在确认前仔细核对地址、凭证和费用信息。</p><h3 id="q-私钥安全吗" tabindex="-1">Q: 私钥安全吗？ <a class="header-anchor" href="#q-私钥安全吗" aria-label="Permalink to &quot;Q: 私钥安全吗？&quot;">​</a></h3><p><strong>A:</strong> 请遵循以下基本原则：</p><ul><li>仅在机器人正式恢复流程中输入凭证</li><li>不要向任何个人、群组、表单或外部网站提供私钥或助记词</li><li>不截图、不转发、不在聊天窗口粘贴凭证</li><li>如果您无法确认当前入口是否为官方机器人，请先停止并核验</li></ul><h3 id="q-如果我有质押的-hype-代币怎么办" tabindex="-1">Q: 如果我有质押的 HYPE 代币怎么办？ <a class="header-anchor" href="#q-如果我有质押的-hype-代币怎么办" aria-label="Permalink to &quot;Q: 如果我有质押的 HYPE 代币怎么办？&quot;">​</a></h3><p><strong>A:</strong> 机器人会自动识别质押所处阶段，并在每次执行后给出下一次运行时间：</p><ul><li>若部分余额已进入下一处理阶段，可能 2 次完成</li><li>若仍需走完整解除质押等待流程，通常需要 3 次</li></ul><h3 id="q-如果我的金库资产被锁定怎么办" tabindex="-1">Q: 如果我的金库资产被锁定怎么办？ <a class="header-anchor" href="#q-如果我的金库资产被锁定怎么办" aria-label="Permalink to &quot;Q: 如果我的金库资产被锁定怎么办？&quot;">​</a></h3><p><strong>A:</strong> 机器人会跳过锁定的金库资产：</p><ul><li>等待锁定期结束</li><li>然后再次运行恢复以提取它们</li></ul><h3 id="q-可以指定提现到特定地址吗" tabindex="-1">Q: 可以指定提现到特定地址吗？ <a class="header-anchor" href="#q-可以指定提现到特定地址吗" aria-label="Permalink to &quot;Q: 可以指定提现到特定地址吗？&quot;">​</a></h3><p><strong>A:</strong> 不可以。恢复流程不需要填写目标地址，资金会提现到源地址对应的 Arbitrum 地址。</p><h3 id="q-恢复失败了怎么办" tabindex="-1">Q: 恢复失败了怎么办？ <a class="header-anchor" href="#q-恢复失败了怎么办" aria-label="Permalink to &quot;Q: 恢复失败了怎么办？&quot;">​</a></h3><p><strong>A:</strong> 先看结果页显示的是哪一种任务级终态：</p><ul><li><code>failed</code>：说明本轮被致命错误中断，请先排查原因后再重试</li><li><code>partial</code>：说明本轮已恢复部分资产，请先查看剩余问题，再决定是否立即再次执行</li><li><code>waiting_to_rerun</code>：说明本轮已成功推进，但仍需等待协议窗口结束后再次执行</li></ul><p>如果最终结果确实是 <code>failed</code>，机器人会在网络故障时自动重试；若仍持续失败：</p><ol><li>检查您的互联网连接</li><li>验证私钥是否正确</li><li>查看错误消息</li><li>如需帮助请联系支持</li></ol><h2 id="💰-费用相关问题" tabindex="-1">💰 费用相关问题 <a class="header-anchor" href="#💰-费用相关问题" aria-label="Permalink to &quot;💰 费用相关问题&quot;">​</a></h2><h3 id="q-恢复费用是多少" tabindex="-1">Q: 恢复费用是多少？ <a class="header-anchor" href="#q-恢复费用是多少" aria-label="Permalink to &quot;Q: 恢复费用是多少？&quot;">​</a></h3><p><strong>A:</strong> 总费用 = 服务费 + 提现手续费</p><ul><li><strong>服务费</strong>: 总资产价值的 0.5%（最低 1 USDC）</li><li><strong>提现手续费</strong>: 2 USDC（Hyperliquid 平台收取）</li></ul><p><strong>示例</strong>:</p><table tabindex="0"><thead><tr><th>您的资产</th><th>服务费</th><th>提现手续费</th><th>总费用</th><th>您收到</th></tr></thead><tbody><tr><td>$100</td><td>$1</td><td>$2</td><td>$3</td><td>$97</td></tr><tr><td>$1,000</td><td>$5</td><td>$2</td><td>$7</td><td>$993</td></tr><tr><td>$10,000</td><td>$50</td><td>$2</td><td>$52</td><td>$9,948</td></tr></tbody></table><h3 id="q-服务费包含哪些内容" tabindex="-1">Q: 服务费包含哪些内容？ <a class="header-anchor" href="#q-服务费包含哪些内容" aria-label="Permalink to &quot;Q: 服务费包含哪些内容？&quot;">​</a></h3><p><strong>A:</strong> 服务费包含：</p><ul><li>所有资产转换（ETH、BTC 等 → USDC）</li><li>所有账户转移（现货 → 永续）</li><li>恢复流程编排与执行服务</li><li>技术支持</li></ul><p><strong>说明：</strong> Hyperliquid 提现手续费不包含在服务费中，会在 <code>Withdrawal Fees</code> 单独计入。</p><h3 id="q-什么时候收取服务费" tabindex="-1">Q: 什么时候收取服务费？ <a class="header-anchor" href="#q-什么时候收取服务费" aria-label="Permalink to &quot;Q: 什么时候收取服务费？&quot;">​</a></h3><p><strong>A:</strong> 服务费在恢复流程的“收取服务费”步骤处理。若执行未进入该步骤，则不会收取服务费。</p><h3 id="q-为什么有提现手续费" tabindex="-1">Q: 为什么有提现手续费？ <a class="header-anchor" href="#q-为什么有提现手续费" aria-label="Permalink to &quot;Q: 为什么有提现手续费？&quot;">​</a></h3><p><strong>A:</strong> Hyperliquid 平台每次提现收取 1 USDC。机器人进行 2 次提现：</p><ol><li>第一次提现：收取服务费（1 USDC）</li><li>第二次提现：发送您的资产（1 USDC） 总计：2 USDC 提现手续费</li></ol><h2 id="🔒-安全相关问题" tabindex="-1">🔒 安全相关问题 <a class="header-anchor" href="#🔒-安全相关问题" aria-label="Permalink to &quot;🔒 安全相关问题&quot;">​</a></h2><h3 id="q-如何确保操作安全" tabindex="-1">Q: 如何确保操作安全？ <a class="header-anchor" href="#q-如何确保操作安全" aria-label="Permalink to &quot;Q: 如何确保操作安全？&quot;">​</a></h3><p><strong>A:</strong> 请遵循以下安全建议：</p><ul><li>在安全的设备和网络环境下操作</li><li>不要在公共场所输入私钥</li><li>仔细验证每个操作步骤</li><li>如果使用共享设备，完成后请及时退出账号并关闭相关聊天窗口</li></ul><h3 id="q-私钥会被保存吗" tabindex="-1">Q: 私钥会被保存吗？ <a class="header-anchor" href="#q-私钥会被保存吗" aria-label="Permalink to &quot;Q: 私钥会被保存吗？&quot;">​</a></h3><p><strong>A:</strong> 本页重点说明用户应如何安全使用：仅在机器人正式恢复流程中输入凭证，不要向任何个人或外部页面提供私钥或助记词，并以交易哈希和链上记录核对结果。</p><h3 id="q-如何防范诈骗" tabindex="-1">Q: 如何防范诈骗？ <a class="header-anchor" href="#q-如何防范诈骗" aria-label="Permalink to &quot;Q: 如何防范诈骗？&quot;">​</a></h3><p><strong>A:</strong> 请注意：</p><ul><li>只使用官方机器人 <a href="https://t.me/HyperliquidRecoveryBot?start=vsAPDn_gitbook" target="_blank" rel="noreferrer">@HyperliquidRecoveryBot</a></li><li>不要在其他地方输入私钥</li><li>除机器人内正式恢复流程外，任何客服、私聊或群组都不会向您索要私钥或助记词</li><li>警惕虚假承诺和不合理的收益保证</li></ul><h3 id="q-发现可疑活动怎么办" tabindex="-1">Q: 发现可疑活动怎么办？ <a class="header-anchor" href="#q-发现可疑活动怎么办" aria-label="Permalink to &quot;Q: 发现可疑活动怎么办？&quot;">​</a></h3><p><strong>A:</strong> 如果发现任何可疑活动：</p><ol><li>立即停止操作</li><li>截图保存证据（不包含敏感信息）</li></ol><h2 id="🔧-技术问题" tabindex="-1">🔧 技术问题 <a class="header-anchor" href="#🔧-技术问题" aria-label="Permalink to &quot;🔧 技术问题&quot;">​</a></h2><h3 id="q-为什么地址验证失败" tabindex="-1">Q: 为什么地址验证失败？ <a class="header-anchor" href="#q-为什么地址验证失败" aria-label="Permalink to &quot;Q: 为什么地址验证失败？&quot;">​</a></h3><p><strong>A:</strong> 可能的原因：</p><ul><li>地址格式不正确（缺少 0x 前缀或长度错误）</li><li>包含无效字符</li><li>复制粘贴时包含了额外的空格或字符</li><li>不是有效的 Hyperliquid (EVM) 地址格式</li></ul><h3 id="q-为什么私钥验证失败" tabindex="-1">Q: 为什么私钥验证失败？ <a class="header-anchor" href="#q-为什么私钥验证失败" aria-label="Permalink to &quot;Q: 为什么私钥验证失败？&quot;">​</a></h3><p><strong>A:</strong> 可能的原因：</p><ul><li>私钥格式与当前输入要求不一致（如前缀或长度不符合）</li><li>私钥长度不正确（应为 64 位十六进制）</li><li>私钥与地址不匹配</li><li>输入时包含了额外字符</li></ul><h3 id="q-网络错误怎么处理" tabindex="-1">Q: 网络错误怎么处理？ <a class="header-anchor" href="#q-网络错误怎么处理" aria-label="Permalink to &quot;Q: 网络错误怎么处理？&quot;">​</a></h3><p><strong>A:</strong> 遇到网络错误时：</p><ol><li>检查网络连接是否稳定</li><li>尝试切换到更稳定的网络</li><li>等待几分钟后重试</li></ol><h3 id="q-api-调用失败怎么办" tabindex="-1">Q: API 调用失败怎么办？ <a class="header-anchor" href="#q-api-调用失败怎么办" aria-label="Permalink to &quot;Q: API 调用失败怎么办？&quot;">​</a></h3><p><strong>A:</strong> API 调用失败可能是因为：</p><ul><li>Hyperliquid API 暂时不可用</li><li>网络连接问题</li><li>请求频率过高</li><li>建议稍后重试</li></ul><h2 id="📱-使用体验问题" tabindex="-1">📱 使用体验问题 <a class="header-anchor" href="#📱-使用体验问题" aria-label="Permalink to &quot;📱 使用体验问题&quot;">​</a></h2><h3 id="q-可以在手机上使用吗" tabindex="-1">Q: 可以在手机上使用吗？ <a class="header-anchor" href="#q-可以在手机上使用吗" aria-label="Permalink to &quot;Q: 可以在手机上使用吗？&quot;">​</a></h3><p><strong>A:</strong> 是的，机器人完全支持手机端使用。建议：</p><ul><li>使用最新版本的 Telegram 应用</li><li>确保手机网络连接稳定</li><li>在安全的环境下操作</li></ul><h3 id="q-界面显示异常怎么办" tabindex="-1">Q: 界面显示异常怎么办？ <a class="header-anchor" href="#q-界面显示异常怎么办" aria-label="Permalink to &quot;Q: 界面显示异常怎么办？&quot;">​</a></h3><p><strong>A:</strong> 如果界面显示异常：</p><ol><li>尝试重新启动 Telegram 应用</li><li>发送 /start 命令重新初始化</li><li>检查 Telegram 应用是否为最新版本</li></ol><h3 id="q-操作响应很慢怎么办" tabindex="-1">Q: 操作响应很慢怎么办？ <a class="header-anchor" href="#q-操作响应很慢怎么办" aria-label="Permalink to &quot;Q: 操作响应很慢怎么办？&quot;">​</a></h3><p><strong>A:</strong> 操作响应慢可能是因为：</p><ul><li>网络连接不稳定</li><li>Telegram 服务器负载较高</li><li>Hyperliquid API 响应较慢</li><li>建议在网络状况良好时操作</li></ul><h2 id="🆘-紧急情况" tabindex="-1">🆘 紧急情况 <a class="header-anchor" href="#🆘-紧急情况" aria-label="Permalink to &quot;🆘 紧急情况&quot;">​</a></h2><h3 id="q-恢复过程中出现错误怎么办" tabindex="-1">Q: 恢复过程中出现错误怎么办？ <a class="header-anchor" href="#q-恢复过程中出现错误怎么办" aria-label="Permalink to &quot;Q: 恢复过程中出现错误怎么办？&quot;">​</a></h3><p><strong>A:</strong> 如果恢复过程中出现错误：</p><ol><li>不要惊慌，记录错误信息</li><li>检查网络连接是否正常</li><li>查看结果页是否为 <code>partial</code> 或 <code>waiting_to_rerun</code>，因为这两种情况不一定表示本轮失败</li></ol><h3 id="q-资产没有到达-arbitrum-地址怎么办" tabindex="-1">Q: 资产没有到达 Arbitrum 地址怎么办？ <a class="header-anchor" href="#q-资产没有到达-arbitrum-地址怎么办" aria-label="Permalink to &quot;Q: 资产没有到达 Arbitrum 地址怎么办？&quot;">​</a></h3><p><strong>A:</strong> 如果资产没有到达源地址对应的 Arbitrum 地址：</p><ol><li>检查交易哈希在区块链浏览器中的状态</li><li>确认源地址是否正确且可在 Arbitrum 正常接收</li><li>等待 Hyperliquid 处理与区块确认（到账可能需要几分钟到十几分钟）</li></ol><h2 id="📊-其他问题" tabindex="-1">📊 其他问题 <a class="header-anchor" href="#📊-其他问题" aria-label="Permalink to &quot;📊 其他问题&quot;">​</a></h2><h3 id="q-可以查看历史操作记录吗" tabindex="-1">Q: 可以查看历史操作记录吗？ <a class="header-anchor" href="#q-可以查看历史操作记录吗" aria-label="Permalink to &quot;Q: 可以查看历史操作记录吗？&quot;">​</a></h3><p><strong>A:</strong> 当前公开文档不再承诺完整的恢复任务历史查询能力；如需核验，请优先依据结果页摘要与交易哈希进行链上核对。</p><h3 id="q-机器人会定期更新吗" tabindex="-1">Q: 机器人会定期更新吗？ <a class="header-anchor" href="#q-机器人会定期更新吗" aria-label="Permalink to &quot;Q: 机器人会定期更新吗？&quot;">​</a></h3><p><strong>A:</strong> 是的，我们会定期更新机器人：</p><ul><li>修复已知问题</li><li>添加新功能</li><li>改进用户体验</li><li>增强安全性</li></ul><h3 id="q-有使用教程或视频吗" tabindex="-1">Q: 有使用教程或视频吗？ <a class="header-anchor" href="#q-有使用教程或视频吗" aria-label="Permalink to &quot;Q: 有使用教程或视频吗？&quot;">​</a></h3><p><strong>A:</strong> 目前提供：</p><ul><li>详细的文字教程</li><li>图文并茂的使用指南</li><li>常见问题解答</li><li>视频教程正在制作中</li><li>可查看本说明文档获取最新指引和更新</li></ul><hr><h2 id="💬-还有其他问题" tabindex="-1">💬 还有其他问题？ <a class="header-anchor" href="#💬-还有其他问题" aria-label="Permalink to &quot;💬 还有其他问题？&quot;">​</a></h2><p>如果您的问题没有在这里找到答案，请：</p><ol><li><p><strong>查看其他文档</strong>：</p><ul><li><a href="./quick-start">快速开始</a></li><li><a href="./bot-usage">机器人使用详解</a></li></ul></li><li><p><strong>通过机器人反馈</strong>：</p><ul><li>提交问题时避免包含敏感信息</li><li>如有错误提示或交易哈希，可一并提供</li></ul></li><li><p><strong>社区支持</strong>：</p><ul><li>加入用户交流群</li><li>查看社区讨论</li><li>分享使用经验</li></ul></li></ol><p><strong>记住</strong>：我们致力于为您提供最好的服务和支持！</p>',134)])])}const p=l(e,[["render",o]]);export{c as __pageData,p as default};
